INSERT INTO `institution_documents` (`id`, `title`, `category`, `programme_id`, `description`, `file_path`, `original_name`, `mime_type`, `size`, `is_public`, `uploaded_by`, `created_at`, `updated_at`) VALUES
(2, 'Practical Procedure Book for Clinical Medicine NTA Level 4', 'practicum_guide', 1, 'This practical procedure book has been developed to support the achievement of competences as stipulated in the curriculum.\r\n\r\nFollowing the review of NTA level 4 curriculum in 2022, there has been a need to review the Practical Procedure Book to accommodate the changes in practical competences.\r\n\r\nThis practical procedure book aims at reinforcing learning in practical skills to students and shall be used as a monitoring tool.', 'institution-documents/practicum_guide/2026/G7yiTiymNHIV7mOW1LKOSmqEd7kcnbZDkM9MpmWt.pdf', 'NTA LEVEL 4 NEW PPB OCT 2022.pdf', 'application/pdf', 434266, 1, 1, '2026-05-28 14:49:23', '2026-05-28 15:29:56'),
(3, 'Practical Procedure Book For Clinical Medicine NTA Level 5', 'practicum_guide', 1, 'This practical procedure book has been developed to support the achievement of competences as stipulated in the curriculum.\r\n\r\nFollowing the review of NTA level 5 curriculum in 2022, there has been a need to review the Practical Procedure Book to accommodate the changes in practical competences.\r\n\r\nThis practical procedure book aims at reinforcing learning in practical skills to students and shall be used as a monitoring tool.', 'institution-documents/practicum_guide/2026/Y2EcJwQtyD4CjLjnH58aKo09fAEzosHxCN0Ziy72.pdf', 'PPB CMT5 OCTOBER 2022, 28 OCTOBER REFINED TODAY FINAL.pdf', 'application/pdf', 651126, 1, 1, '2026-05-28 14:54:49', '2026-05-28 15:29:46'),
(4, 'Practical Procedure Book  For  Clinical Medicine NTA Level 6', 'practicum_guide', 1, 'This practical procedure book has been developed to support the achievement of competences as stipulated in the curriculum.\r\n\r\nFollowing the review of NTA level 6 curriculum in 2022, there has been a need to review the Practical Procedure Book to accommodate the changes in practical competences.\r\n\r\nThis practical procedure book aims at reinforcing learning in practical skills to students and shall be used as a monitoring tool.', 'institution-documents/practicum_guide/2026/YgFUcjvwaCS5IFoRrgCqL5xgMEPve7UJyS5k0uCe.pdf', 'CMT NTA LEVEL 6 NEW PPB October 2022 TODAY.pdf', 'application/pdf', 591910, 1, 1, '2026-05-28 14:57:56', '2026-05-28 15:29:31'),
(5, 'ASSESSMENT PLAN FOR NTA LEVEL 4 SEMESTER 1 (Basic Technician Certificate Course in Medical Laboratory Sciences)', 'assessment_plan', 2, 'The development of these Assessment Plans for the Basic Technician Certificate (NTA level 4) in Medical Laboratory Sciences programme is an outcome of collaborative efforts of the Ministry of Health (MoH), National Council for Technical and Vocational Education and Training (NACTVET) and tutors from various Health Training Institutions.', 'institution-documents/assessment_plan/2026/BsLcu3yydtUEFhEAKyC2d6k9eZs4y1TVXDhdnRX2.pdf', 'ASSESSMENT-PLAN-MLT-LEVEL-4-OCT_DONE.pdf', 'application/pdf', 821076, 1, 1, '2026-05-28 15:00:41', '2026-05-28 15:30:36'),
(6, 'ASSESSMENT PLANS FOR TECHNICIAN CERTIFICATE (NTA LEVEL 5)  IN MEDICAL LABORATORY SCIENCES', 'assessment_plan', 2, 'The development of these Assessment Plans for Technician Certificate (NTA level 5) in Medical Laboratory Sciences programme is an outcome of collaborative efforts of the Ministry of Health (MoH), National Council for Technical and Vocational Education and Training (NACTVET) and tutors from various Health Training Institutions.', 'institution-documents/assessment_plan/2026/jFOvMrTgfI2pPwtX07oDlH6TVK890V9I6Mzdj2MC.pdf', 'ASSESSMENT-PLAN-MLT-LEVEL-5-OCT_-DONE.pdf', 'application/pdf', 858318, 1, 1, '2026-05-28 15:01:54', '2026-05-28 15:30:27'),
(7, 'Assessment Plans for Ordinary Diploma (NTA Level 6)  in Medical Laboratory Sciences', 'assessment_plan', 2, 'The development of these Assessment Plans for Ordinary Diploma (NTA level 6) in Medical Laboratory Sciences programme is an outcome of collaborative efforts of the Ministry of Health (MoH), National Council for Technical and Vocational Education and Training (NACTVET) and tutors from various Health Training Institutions.', 'institution-documents/assessment_plan/2026/z3JlOd6E3xixSyp1eLsOYjgjwcw0sylJYbSA5Zyb.pdf', 'ASSESSMENT-PLAN-MLT-LEVEL-6-OCT_DONE.pdf', 'application/pdf', 831498, 1, 1, '2026-05-28 15:03:51', '2026-05-28 15:30:14'),
(8, 'Practicum Guide For Students  NTA level 5 Medical Laboratory Sciences', 'practicum_guide', 2, 'The practicum guide for students has been developed to guide students in the practical areas in transferring the theoretical knowledge into practice. \r\n\r\nIt provides an opportunity for students to practice newly learned skills under the supervision and support of tutors and practical instructors.', 'institution-documents/practicum_guide/2026/1oL8gViNCvdQh2qzxizWUgWgOENS5hnj5u3PSExh.pdf', 'MLT-5-PRACTICUM-GUIDE-FOR-STUDENTS.pdf', 'application/pdf', 745011, 1, 1, '2026-05-28 15:21:57', '2026-05-28 15:29:19'),
(9, 'Practicum Guide For Students  NTA level 4 Medical Laboratory  Sciences', 'practicum_guide', 2, 'The practicum guide has been developed to guide students to effectively learn in laboratory practical areas to transfer\r\nthe theoretical knowledge into practice. \r\n\r\nIt provides an opportunity for students to practice newly learned skills under the supervision and support of tutors and practical instructors.', 'institution-documents/practicum_guide/2026/lOdJ7IYB5dvR0kKi0b8fdDnXFlBmbNaGLsC1Mjxm.pdf', 'MLT-5-PRACTICUM-GUIDE-FOR-STUDENTS.pdf', 'application/pdf', 745011, 1, 1, '2026-05-28 15:23:31', '2026-05-28 15:29:00');
